"""Real JEE Main questions — Mathematics Unit 10: Coordinate Geometry. Our own solutions; chk re-solves each one
numerically from the raw data — intersection points by solving the equations, centres of triangles from their
vertices, conic parameters by searching for the values that satisfy every condition, and tangency by the
discriminant of the substituted quadratic. Skipped: an item whose answer key we could not reproduce from the printed
data and an item whose option set does not fit the circle described."""
import math, itertools
from fractions import Fraction as F
from common import new_registry, pick, verify
P, add = new_registry()
S2, S3, S5 = math.sqrt(2), math.sqrt(3), math.sqrt(5)
def inter(l1, l2):   # lines a x + b y = c
    (a1, b1, c1), (a2, b2, c2) = l1, l2; D = a1 * b2 - a2 * b1; return ((c1 * b2 - c2 * b1) / D, (a1 * c2 - a2 * c1) / D)
def line_pts(p, q): return (q[1] - p[1], p[0] - q[0], (q[1] - p[1]) * p[0] + (p[0] - q[0]) * p[1])
def ortho(A, B, C):
    l1 = (C[0] - B[0], C[1] - B[1], (C[0] - B[0]) * A[0] + (C[1] - B[1]) * A[1]); l2 = (C[0] - A[0], C[1] - A[1], (C[0] - A[0]) * B[0] + (C[1] - A[1]) * B[1]); return inter(l1, l2)
def circum(A, B, C):
    l1 = (B[0] - A[0], B[1] - A[1], (B[0] ** 2 - A[0] ** 2 + B[1] ** 2 - A[1] ** 2) / 2); l2 = (C[0] - A[0], C[1] - A[1], (C[0] ** 2 - A[0] ** 2 + C[1] ** 2 - A[1] ** 2) / 2); return inter(l1, l2)
def dist(p, q): return math.hypot(p[0] - q[0], p[1] - q[1])
def dpl(p, l): a, b, c = l; return abs(a * p[0] + b * p[1] - c) / math.hypot(a, b)
def refl(p, l): a, b, c = l; t = (a * p[0] + b * p[1] - c) / (a * a + b * b); return (p[0] - 2 * a * t, p[1] - 2 * b * t)
def area(*V): return abs(sum(V[i][0] * V[(i + 1) % len(V)][1] - V[(i + 1) % len(V)][0] * V[i][1] for i in range(len(V)))) / 2
def qr(a, b, c):
    d = b * b - 4 * a * c; return sorted([(-b - math.sqrt(d)) / (2 * a), (-b + math.sqrt(d)) / (2 * a)]) if d >= 0 else []
def near(x, y, t=1e-6): return abs(x - y) <= t * max(1, abs(y))
def P4(opts, v, tol=1e-6): return pick(opts, round(v, 9), tol)
def bisect(f, lo, hi):
    for _ in range(200):
        m = (lo + hi) / 2
        if f(lo) * f(m) <= 0: hi = m
        else: lo = m
    return (lo + hi) / 2

